function tr(text) {
    if (text === null || text === undefined) return text;
    var value = String(text);
    var selectedLanguage = Config.GlobalConfig.general.language || Qt.locale().name;
    if (!/^es([_-]|$)/i.test(selectedLanguage)) return value;
    if (Object.prototype.hasOwnProperty.call(messages, value)) return messages[value];
    // Native plural translation has already substituted %n.
    var patterns = [
        [ /^(\d+) notifications$/, "$1 notificaciones" ],
        [ /^(\d+) notification$/, "$1 notificación" ],
        [ /^1 day$/, "1 día" ],
        [ /^(\d+) days$/, "$1 días" ],
        [ /^(\d+) hours$/, "$1 horas" ],
        [ /^(\d+) hour$/, "$1 hora" ],
        [ /^(\d+) mins?$/, "$1 min" ],
        [ /^(\d+) minutes$/, "$1 minutos" ],
        [ /^(\d+) minute$/, "$1 minuto" ],
        [ /^(\d+) network available$/, "$1 red disponible" ],
        [ /^(\d+) networks available$/, "$1 redes disponibles" ],
        [ /^(\d+) device available(.*)$/, "$1 dispositivo disponible$2" ],
        [ /^(\d+) devices available(.*)$/, "$1 dispositivos disponibles$2" ],
        [ /^(\d+) app playing audio$/, "$1 aplicación reproduciendo audio" ],
        [ /^(\d+) apps playing audio$/, "$1 aplicaciones reproduciendo audio" ] ];
    for (var i = 0; i < patterns.length; i++)
        if (patterns[i][0].test(value)) return value.replace(patterns[i][0], patterns[i][1]);
    return value;
}
